//! INTERIM(L5): the wide base loader (the BW package, adopted
//! 2026-11-17): GNU R 4.6.2's own base R code, read from the pinned source
//! tarball's tree (`scripts/r-src.sh`, L4: never `rlib/`), every binding
//! GNU R makes in base bound into the base environment. L5's boot from GNU
//! R-built databases replaces it, and deletes it with `proto/base-wide.txt`,
//! `proto/base-bound.txt`, `proto/base-subset.txt` and
//! `scripts/base-subset.sh`.
//!
//! What it binds is `proto/base-wide.txt` (generated by
//! `scripts/base-subset.sh` with `scripts/base-wide.R` on GNU R 4.6.2):
//! each name of `ls(baseenv(), all.names = TRUE)` with the form that defines
//! it. That is the last top-level assignment to it in base's files in
//! collation order (`LC_COLLATE=C ls R/*.R R/unix/*.R`, base's Makefile),
//! as GNU R's build evaluates their concatenation, an inner name of a chain
//! (`licence <- license <- function()`) included; or the `local()` that
//! assigns it (zzz.R's deprecated `as.data.frame.<class>` methods,
//! baseloader.R's native symbols); or the system profile's assignment
//! (`T`, `R.version`, `.Library`), as R_LoadProfile evaluates it in base.
//! The forms that bind nothing are classified by the generator, which fails
//! on one it does not know: those that change a binding run right after
//! its definition (zzz.R's `assign()`s into `.ArgsEnv`, baseloader.R's S3
//! methods registration and locks), the rest bind nothing base has, or are
//! not run with a record ([`Wide::skips`]), and a name whose definition
//! needs one raises when touched, naming it.
//!
//! Bindings are lazy, as GNU R's are: GNU R loads base from its lazy-load
//! database, so every base variable starts as a promise that fetches the
//! value on first use (`lazyLoad`, `makeLazy`, PRCODE
//! `lazyLoadDBfetch(key, ...)`). Here the promise's code is a call of the
//! fetch `.Internal` on the name ([`base_fetch`]), evaluated in the base
//! namespace on first use: it reads that form's bytes from the tree,
//! parses and evaluates its right-hand side there (for a function literal,
//! the closure GNU R stored, its environment the base namespace), and runs
//! the forms that follow the definition. Loading runs only the profile's
//! forms whose effect depends on when they run (`boot`: the Autoloads
//! environment GNU R's profile attaches, and `.AutoloadEnv`, at the point
//! R_LoadProfile runs them); the cost of every binding is paid by the
//! process that uses it.
//!
//! Every primitive and `.Internal` of GNU R 4.6.2 that robigo-rt does not
//! implement is bound to a builtin that raises "robigo: ... is not
//! implemented yet" (AGENTS rule 6), so that reaching one says so instead
//! of "could not find function".

#![allow(unsafe_code)]

use crate::prims::{Kind, PrimDef};
use robigo_heap::types::*;
use robigo_rtcore::{Args, Cx, Out, RResult, Ref, Root, Sexp};
use std::path::{Path, PathBuf};

/// The sha256 of the pinned GNU R 4.6.2 tarball, `scripts/r-src.sh`'s pin
/// (a test checks the two agree).
pub const RSRC_SHA256: &str = "c297040f6392b1dac6e5c0eb398422cfdaedf540ae2205edb9ad0d10cb10ee00";

/// The bound, as generated.
const BOUND: &str = include_str!("../proto/base-bound.txt");

/// One closure of the bound: its name and the file of `src/library/base/R`
/// whose last top-level assignment defines it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct BoundClosure {
    pub name: &'static str,
    pub file: &'static str,
    /// A base variable a bound closure names (`letters`), not a function.
    pub variable: bool,
}

/// `proto/base-bound.txt`, parsed.
#[derive(Debug)]
pub struct Bound {
    pub closures: Vec<BoundClosure>,
    pub primitives: Vec<&'static str>,
    pub internals: Vec<&'static str>,
}

impl Bound {
    /// The bound compiled into this binary. Panics if the file is malformed
    /// (a test reads it).
    pub fn get() -> &'static Bound {
        static B: std::sync::OnceLock<Bound> = std::sync::OnceLock::new();
        B.get_or_init(|| Bound::parse(BOUND).unwrap_or_else(|e| panic!("robigo: proto/base-bound.txt: {e}")))
    }

    fn parse(text: &'static str) -> Result<Bound, String> {
        let mut b = Bound { closures: Vec::new(), primitives: Vec::new(), internals: Vec::new() };
        for (i, line) in text.lines().enumerate() {
            if line.starts_with('#') || line.is_empty() {
                continue;
            }
            let f: Vec<&'static str> = line.split(' ').collect();
            match (f[0], f.len()) {
                // a variable binds as a closure does: its definition, lazily
                (k @ ("closure" | "variable"), 3) => {
                    b.closures.push(BoundClosure { name: f[1], file: f[2], variable: k == "variable" })
                }
                ("primitive", 2) => b.primitives.push(f[1]),
                ("internal", 2) => b.internals.push(f[1]),
                _ => return Err(format!("line {}: {line:?}", i + 1)),
            }
        }
        Ok(b)
    }

    /// The files to read, in base's collation order: `R/*.R`, then
    /// `R/unix/*.R`, each sorted by bytes (`LC_COLLATE=C ls`).
    pub fn files(&self) -> Vec<&'static str> {
        let mut v: Vec<&'static str> = self.closures.iter().map(|c| c.file).collect();
        v.sort_by_key(|f| (f.contains('/'), *f));
        v.dedup();
        v
    }
}

/// INTERIM(L5): the wide base, as generated.
const WIDE: &str = include_str!("../proto/base-wide.txt");

/// A top-level form of a file under the tarball's `src/library`
/// (`base/R/zzz.R`, `profile/Common.R`): its bytes `[start, end)`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Form {
    pub src: &'static str,
    pub start: usize,
    pub end: usize,
}

/// How a name of the wide base gets its value on first use.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Def {
    /// The right-hand side of the assignment at that depth (0: the outer)
    /// of the chain each form is. One, unless the name's last definition
    /// reads the name (the profile's `.Library.site`): then each runs in
    /// order, the name bound to the value before it.
    Assign(Vec<(Form, usize)>),
    /// What the form, a `local()`, assigns into the base namespace: run
    /// once, for every name it binds.
    Block(Form),
    /// Its definition needs this form, which is not run: it raises.
    Unrun(Form),
}

/// One name of the wide base.
#[derive(Clone, Debug)]
pub struct WideName {
    pub name: &'static str,
    pub def: Def,
    /// The forms that run right after its definition, in order (zzz.R's
    /// `assign()`s into `.ArgsEnv`, baseloader.R's lock of it).
    pub after: Vec<Form>,
}

/// INTERIM(L5): `proto/base-wide.txt`, parsed: every binding GNU R 4.6.2
/// makes in base.
#[derive(Debug)]
pub struct Wide {
    /// The names bound lazily, in the index's order.
    pub names: Vec<WideName>,
    /// The forms that are not run, and why (the skip record).
    pub skips: Vec<(Form, &'static str)>,
    /// The forms run at startup, in order, in the base namespace before
    /// its locks (the profile's Autoloads environment and `.AutoloadEnv`).
    pub boot: Vec<Form>,
    /// The names GNU R's C binds at startup.
    pub from_c: Vec<&'static str>,
    /// configure's substitutions in base's sources (mkRbase's sed).
    pub substs: Vec<(&'static str, &'static str)>,
    pub primitives: Vec<&'static str>,
    pub internals: Vec<&'static str>,
    by_name: std::collections::HashMap<&'static str, usize>,
}

impl Wide {
    /// The wide base compiled into this binary. Panics if the file is
    /// malformed (a test reads it).
    pub fn get() -> &'static Wide {
        static W: std::sync::OnceLock<Wide> = std::sync::OnceLock::new();
        W.get_or_init(|| Wide::parse(WIDE).unwrap_or_else(|e| panic!("robigo: proto/base-wide.txt: {e}")))
    }

    fn parse(text: &'static str) -> Result<Wide, String> {
        let mut w = Wide {
            names: Vec::new(),
            skips: Vec::new(),
            boot: Vec::new(),
            from_c: Vec::new(),
            substs: Vec::new(),
            primitives: Vec::new(),
            internals: Vec::new(),
            by_name: std::collections::HashMap::new(),
        };
        let num = |s: &str, i: usize| s.parse::<usize>().map_err(|_| format!("line {}: not a number: {s:?}", i + 1));
        let mut after: Vec<(&'static str, Form)> = Vec::new();
        for (i, line) in text.lines().enumerate() {
            if line.starts_with('#') || line.is_empty() {
                continue;
            }
            let f: Vec<&'static str> = line.splitn(5, ' ').collect();
            let bad = || format!("line {}: {line:?}", i + 1);
            let form = |src: &'static str, a: &str, b: &str| -> Result<Form, String> {
                Ok(Form { src, start: num(a, i)?, end: num(b, i)? })
            };
            match f[0] {
                "def" if f.len() == 5 => {
                    // NAME SRC START END DEPTH [seq]
                    let g: Vec<&'static str> = line.split(' ').collect();
                    let (name, fm, depth) = match g.len() {
                        6 | 7 => (g[1], form(g[2], g[3], g[4])?, num(g[5], i)?),
                        _ => return Err(bad()),
                    };
                    let seq = g.len() == 7 && g[6] == "seq";
                    match w.names.last_mut() {
                        Some(WideName { name: n, def: Def::Assign(v), .. }) if seq && *n == name => v.push((fm, depth)),
                        _ => w.names.push(WideName { name, def: Def::Assign(vec![(fm, depth)]), after: Vec::new() }),
                    }
                }
                "block" if f.len() == 5 => {
                    let g: Vec<&'static str> = line.split(' ').collect();
                    w.names.push(WideName { name: g[1], def: Def::Block(form(g[2], g[3], g[4])?), after: Vec::new() })
                }
                "unrun" if f.len() == 5 => {
                    let g: Vec<&'static str> = line.split(' ').collect();
                    w.names.push(WideName { name: g[1], def: Def::Unrun(form(g[2], g[3], g[4])?), after: Vec::new() })
                }
                "after" if f.len() == 5 => {
                    let g: Vec<&'static str> = line.split(' ').collect();
                    after.push((g[1], form(g[2], g[3], g[4])?))
                }
                // SRC START END WHY (the rest of the line)
                "skip" if f.len() == 5 => w.skips.push((form(f[1], f[2], f[3])?, f[4])),
                "boot" if f.len() == 4 => w.boot.push(form(f[1], f[2], f[3])?),
                "c" if f.len() == 2 => w.from_c.push(f[1]),
                "subst" if f.len() == 3 => w.substs.push((f[1], f[2])),
                "primitive" if f.len() == 2 => w.primitives.push(f[1]),
                "internal" if f.len() == 2 => w.internals.push(f[1]),
                _ => return Err(bad()),
            }
        }
        for (i, n) in w.names.iter().enumerate() {
            if w.by_name.insert(n.name, i).is_some() {
                return Err(format!("'{}' is defined twice", n.name));
            }
        }
        for (target, fm) in after {
            let Some(&i) = w.by_name.get(target) else {
                return Err(format!("a form runs after '{target}', which is not defined"));
            };
            w.names[i].after.push(fm);
        }
        Ok(w)
    }

    /// The name `name`'s entry.
    pub fn find(&self, name: &str) -> Option<&WideName> {
        self.by_name.get(name).map(|&i| &self.names[i])
    }

    /// The files the definitions are read from, each once.
    pub fn files(&self) -> Vec<&'static str> {
        let mut v: Vec<&'static str> = Vec::new();
        for n in &self.names {
            let forms: Vec<Form> = match &n.def {
                Def::Assign(d) => d.iter().map(|&(f, _)| f).collect(),
                Def::Block(f) | Def::Unrun(f) => vec![*f],
            };
            v.extend(forms.iter().chain(n.after.iter()).map(|f| f.src));
        }
        v.extend(self.boot.iter().map(|f| f.src));
        v.sort_unstable();
        v.dedup();
        v
    }

    /// Why `form` is not run, if it is one of the skipped.
    pub fn skipped(&self, form: Form) -> Option<&'static str> {
        self.skips.iter().find(|(f, _)| *f == form).map(|&(_, why)| why)
    }
}

/// The extracted tree of the pinned GNU R 4.6.2 sources: `ROBIGO_RSRC` if
/// set, else where `scripts/r-src.sh` extracts it
/// (`${ROBIGO_RESEARCH_CACHE:-~/.cache/robigo-research}/rsrc/R-4.6.2-<sha256[..12]>`).
/// Either must carry `r-src.sh`'s stamp of the pinned hash.
pub fn source_dir() -> Result<PathBuf, String> {
    let dir = match std::env::var_os("ROBIGO_RSRC") {
        Some(d) => PathBuf::from(d),
        None => {
            let cache = match std::env::var_os("ROBIGO_RESEARCH_CACHE") {
                Some(c) => PathBuf::from(c),
                None => match std::env::var_os("HOME") {
                    Some(h) => Path::new(&h).join(".cache/robigo-research"),
                    None => return Err("neither ROBIGO_RSRC nor HOME is set".into()),
                },
            };
            cache.join("rsrc").join(format!("R-4.6.2-{}", &RSRC_SHA256[..12]))
        }
    };
    let stamp = dir.join(".rsrc-pinned");
    match std::fs::read_to_string(&stamp) {
        Ok(s) if s.trim() == RSRC_SHA256 => Ok(dir),
        Ok(_) => Err(format!("{} is not the pinned GNU R 4.6.2 tree (its stamp differs)", dir.display())),
        Err(_) => Err(format!(
            "GNU R 4.6.2's sources are not at {} (run scripts/r-src.sh, or set ROBIGO_RSRC)",
            dir.display()
        )),
    }
}

/// What [`load`] did.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Loaded {
    /// The files the lazy bindings read their definitions from.
    pub files: usize,
    /// The names bound lazily.
    pub closures: usize,
    /// Primitives and internals bound to "not implemented yet".
    pub stubs: usize,
}

/// The name of the fetch `.Internal` the lazy bindings call (no base
/// binding has it: `.Internal`s live in the symbols' internal slots).
const FETCH: &str = "..robigo_base_fetch";

/// INTERIM(L5): bind the wide base into `cx`'s base environment from the
/// tree `dir` ([`source_dir`]), each name lazily ([`Wide`]). Run after
/// [`crate::install`]: the stubs go only where no primitive or internal of
/// that name is defined. Reads only the `boot` forms' file: an error names
/// a file the tree lacks. `ROBIGO_BOOT_VERBOSE=1` prints the forms that are not run.
pub fn load(cx: &mut Cx, dir: &Path) -> Result<Loaded, String> {
    let wide = Wide::get();
    let lib = dir.join("src/library");
    let files = wide.files();
    for f in &files {
        let p = lib.join(f);
        if !p.is_file() {
            return Err(format!("{} is missing", p.display()));
        }
    }
    *crate::prims::state(cx).base_src.borrow_mut() = Some(lib.clone());
    let fetch = fetch_internal(cx);
    for n in &wide.names {
        bind_wide(cx, n.name, &fetch).map_err(|e| format!("binding '{}': {e}", n.name))?;
    }
    init_graphics(cx).map_err(|e| format!("binding .Device: {e}"))?;
    let stubs = bind_stubs_wide(cx, wide);
    // the profile's forms that cannot wait (R_LoadProfile runs them all at
    // this point; the rest are among the lazy bindings)
    for &form in &wide.boot {
        cx.building_base(|cx| {
            cx.scope(|cx, s| {
                let o = s.out(cx);
                eval_form(cx, form, o, |e| Some(e))
            })
        })
        .map_err(|e| format!("{}: {}", where_is(&lib, form), failed(cx, e)))?;
    }
    // this is the point after R_LoadProfile
    lock_base(cx).map_err(|e| failed(cx, e))?;
    if std::env::var_os("ROBIGO_BOOT_VERBOSE").is_some_and(|v| !v.is_empty() && v != "0") {
        for (f, why) in &wide.skips {
            eprintln!("robigo-rt: base's {} not run: {why} (INTERIM(L5))", where_is(&lib, *f));
        }
    }
    Ok(Loaded { files: files.len(), closures: wide.names.len(), stubs })
}

/// The fetch `.Internal`'s object, defined on first use.
fn fetch_internal(cx: &mut Cx) -> robigo_rtcore::Global {
    let find = |cx: &Cx| crate::prims::state(cx).defs.iter().position(|d| d.name == FETCH && d.internal());
    if find(cx).is_none() {
        crate::define_builtins(cx, &[PrimDef { name: FETCH, kind: Kind::Fn(base_fetch), eval: 10, arity: 1 }]);
    }
    let i = find(cx).expect("robigo: the base fetch");
    let st = crate::prims::state(cx);
    cx.global(st.objs[i].bind(cx))
}

/// Bind `name` in base to a promise of `(<fetch> name)` in the base
/// namespace; a binding of one of cmp.R's `safeBaseInternals` is kept as
/// base's shipped definition.
fn bind_wide(cx: &mut Cx, name: &str, fetch: &robigo_rtcore::Global) -> Result<(), String> {
    cx.scope(|cx, s| {
        let sym = s.out(cx);
        let symr = sym.root();
        cx.build(sym, |cx| Ok(cx.install(name.as_bytes())?.as_ref())).map_err(|e| failed(cx, e))?;
        let code = s.out(cx);
        let code_r = code.root();
        cx.build(code, |cx| {
            let arg = cx.cons(symr.bind(cx), cx.nil())?;
            cx.lcons(fetch.bind(cx), arg)
        })
        .map_err(|e| failed(cx, e))?;
        bind_promise(cx, symr, code_r)
    })
}

/// `.Device` and `.Devices` in base, as GNU R's graphics startup makes
/// them (no device open).
// R: devices.c:InitGraphics
fn init_graphics(cx: &mut Cx) -> Result<(), String> {
    cx.scope(|cx, s| {
        let base = s.root(cx, cx.base_env());
        let dev = s.out(cx);
        let devr = dev.root();
        cx.build(dev, |cx| cx.mk_string(b"null device", robigo_rtcore::Encoding::Native)).map_err(|e| failed(cx, e))?;
        let sym = cx.install_rooted(s, b".Device").map_err(|e| failed(cx, e))?;
        cx.define_var(sym, devr, base).map_err(|e| failed(cx, e))?;
        let devs = s.out(cx);
        let devsr = devs.root();
        cx.build(devs, |cx| {
            let d = cx.mk_string(b"null device", robigo_rtcore::Encoding::Native)?;
            cx.cons(d, cx.nil())
        })
        .map_err(|e| failed(cx, e))?;
        let sym = cx.install_rooted(s, b".Devices").map_err(|e| failed(cx, e))?;
        cx.define_var(sym, devsr, base).map_err(|e| failed(cx, e))
    })
}

/// `FILE:LINE` of `form` in the tree `lib`.
fn where_is(lib: &Path, form: Form) -> String {
    let line = std::fs::read(lib.join(form.src))
        .map(|b| b[..form.start.min(b.len())].iter().filter(|&&c| c == b'\n').count() + 1)
        .unwrap_or(0);
    format!("{}:{line}", form.src)
}

/// The bytes of `form`, read from the tree, with configure's substitutions
/// made.
fn form_bytes(cx: &Cx, form: Form) -> Result<Vec<u8>, String> {
    use std::io::{Read, Seek, SeekFrom};
    let lib = crate::prims::state(cx).base_src.borrow().clone().ok_or("the base sources are not loaded")?;
    let path = lib.join(form.src);
    let mut f = std::fs::File::open(&path).map_err(|e| format!("{}: {e}", path.display()))?;
    let mut b = vec![0u8; form.end - form.start];
    f.seek(SeekFrom::Start(form.start as u64))
        .and_then(|_| f.read_exact(&mut b))
        .map_err(|e| format!("{}: {e}", path.display()))?;
    for &(from, to) in &Wide::get().substs {
        b = sed_first_per_line(&b, from.as_bytes(), to.as_bytes());
    }
    Ok(b)
}

/// `sed -e "s:FROM:TO:"` (mkRbase's, share/make/basepkg.mk): the first
/// occurrence of `from` on each line replaced by `to` (no `g` flag).
fn sed_first_per_line(b: &[u8], from: &[u8], to: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(b.len());
    for line in b.split_inclusive(|&c| c == b'\n') {
        match line.windows(from.len()).position(|w| w == from) {
            Some(k) => {
                out.extend_from_slice(&line[..k]);
                out.extend_from_slice(to);
                out.extend_from_slice(&line[k + from.len()..]);
            }
            None => out.extend_from_slice(line),
        }
    }
    out
}

/// Parse `form`, take the expression `pick` gives of its one top-level
/// expression, lower it (its function literals marked as base's installed
/// byte code) and evaluate it in the base namespace into `out`.
fn eval_form(
    cx: &mut Cx,
    form: Form,
    out: Out<'_>,
    pick: impl for<'a> FnOnce(&'a robigo_syntax::Expr<'a>) -> Option<&'a robigo_syntax::Expr<'a>>,
) -> RResult<()> {
    let bytes = form_bytes(cx, form).map_err(|m| cx.error(&format!("robigo: reading base: {m}")))?;
    let text = robigo_syntax::lexable(&bytes);
    let source = robigo_syntax::Source::new(&text, &bytes);
    let arena = robigo_syntax::Arena::new();
    let exprs = match robigo_syntax::parse_program(&arena, source) {
        Ok(e) if e.len() == 1 => e,
        _ => return Err(cx.error(&format!("robigo: base's {} {}..{} is not one form", form.src, form.start, form.end))),
    };
    let Some(e) = pick(&exprs[0]) else {
        return Err(
            cx.error(&format!("robigo: base's {} {}..{} is not the definition", form.src, form.start, form.end))
        );
    };
    cx.scope(|cx, s| {
        let code = s.out(cx);
        let code_r = code.root();
        crate::reader::lower_one(cx, e, code)?;
        // SAFETY: the rooted, freshly lowered code, which no R code has seen.
        unsafe { mark_literals(cx, code_r.bind(cx).sexp()) };
        let ns = s.root(cx, cx.base_namespace());
        crate::eval::eval(cx, code_r, ns, out)
    })
}

/// INTERIM(L5): the fetch `.Internal` of the wide base's lazy bindings
/// (`(<fetch> NAME)`, a promise's code): NAME's definition evaluated in the
/// base namespace ([`Def`]), then the forms that follow it; the value into
/// `out`, which the promise keeps. GNU R's lazy-load promise fetches a
/// value its build computed; this computes it on first use.
fn base_fetch(cx: &mut Cx, call: Root<'_>, _: Root<'_>, _: Root<'_>, out: Out<'_>) -> RResult<()> {
    let name = call
        .bind(cx)
        .as_cons()
        .and_then(|c| c.cdr().as_cons())
        .and_then(|a| a.car().as_sym())
        .map(|s| String::from_utf8_lossy(s.name_bytes()).into_owned());
    let wide = Wide::get();
    let Some(w) = name.as_deref().and_then(|n| wide.find(n)) else {
        return Err(cx.error("robigo: a fetch of no name of base"));
    };
    let res = out.root();
    cx.scope(|cx, s| {
        let sym = cx.install_rooted(s, w.name.as_bytes())?;
        let base = s.root(cx, cx.base_env());
        let o = s.out(cx);
        let promise = o.root();
        cx.find_var_in_frame3(base, sym, true, o)?;
        // (base's build-time code, run late: past the locks on base)
        let r = cx.building_base(|cx| fetch_steps(cx, w, sym, base, res));
        // a step failed after one rebound the name: the fetch's promise again,
        // so the name raises again when touched (as a lazy-load promise whose
        // fetch failed), not an intermediate value
        if r.is_err() && is_fetch(cx, promise.bind(cx).sexp()) {
            let o = s.out(cx);
            let now = o.root();
            cx.find_var_in_frame3(base, sym, true, o)?;
            if now.bind(cx).sexp() != promise.bind(cx).sexp() {
                cx.building_base(|cx| cx.define_var(sym, promise, base))?;
            }
        }
        r
    })
}

/// [`base_fetch`]'s steps for `w`, its value into `res`. A name defined in
/// more than one step (`seq` definitions, forms after its definition) is
/// rebound along the way, the later steps reading it: bound to its final
/// value at the end, which its promise keeps too.
fn fetch_steps(cx: &mut Cx, w: &WideName, sym: Root<'_>, base: Root<'_>, res: Root<'_>) -> RResult<()> {
    let wide = Wide::get();
    cx.scope(|cx, s| {
        let rebinds = match &w.def {
            Def::Assign(defs) => {
                for (k, &(form, depth)) in defs.iter().enumerate() {
                    let o = res.reset(cx);
                    eval_form(cx, form, o, |e| {
                        let mut e = e;
                        for _ in 0..depth {
                            e = assignment(e)?.1;
                        }
                        assignment(e).map(|(_, rhs)| rhs)
                    })?;
                    // (a later definition reads the name: bound to this)
                    if k + 1 < defs.len() {
                        cx.define_var(sym, res, base)?;
                    }
                }
                defs.len() > 1
            }
            Def::Block(form) => {
                let o = s.out(cx);
                eval_form(cx, *form, o, |e| Some(e))?;
                let o = res.reset(cx);
                cx.find_var_in_frame3(base, sym, true, o)?;
                if is_fetch(cx, res.bind(cx).sexp()) {
                    let m = format!("robigo: base's {} did not bind '{}'", form.src, w.name);
                    return Err(cx.error(&m));
                }
                false
            }
            Def::Unrun(form) => {
                let lib = crate::prims::state(cx).base_src.borrow().clone().unwrap_or_default();
                let why = wide.skipped(*form).unwrap_or("not run");
                let m = format!(
                    "robigo: '{}' needs base's {}, which robigo-rt does not run: {why} (INTERIM(L5))",
                    w.name,
                    where_is(&lib, *form)
                );
                return Err(cx.error(&m));
            }
        };
        if rebinds || !w.after.is_empty() {
            // the final value; the forms that follow read the name
            cx.define_var(sym, res, base)?;
        }
        for &form in &w.after {
            let o = s.out(cx);
            eval_form(cx, form, o, |e| Some(e))?;
        }
        Ok(())
    })
}

/// Whether `x` is a promise of the wide base not yet replaced: its code a
/// call of the fetch.
fn is_fetch(cx: &Cx, x: Sexp) -> bool {
    // SAFETY: a live object; a promise's code is live.
    unsafe {
        if x.typ() != PROMSXP {
            return false;
        }
        let code = x.cdr();
        code.typ() == LANGSXP && {
            let f = code.car();
            f.typ() == SPECIALSXP
                && crate::prims::state(cx).defs.get(crate::prims::offset(f)).is_some_and(|d| d.name == FETCH)
        }
    }
}

/// Bind the wide base's primitives and internals that robigo-rt does not
/// define to the not-implemented builtins; how many.
fn bind_stubs_wide(cx: &mut Cx, wide: &Wide) -> usize {
    stubs_for(cx, &wide.primitives, &wide.internals)
}
/// A top-level `NAME <- RHS` or `NAME = RHS` (`"NAME" <- RHS` too): the
/// name's bytes and the right-hand side.
fn assignment<'a>(e: &'a robigo_syntax::Expr<'a>) -> Option<(&'a [u8], &'a robigo_syntax::Expr<'a>)> {
    use robigo_syntax::{Const, Expr};
    let Expr::Call { fun: Expr::Sym(op, _), args, .. } = e else { return None };
    if !matches!(*op, "<-" | "=") || args.len() != 2 || args.iter().any(|a| a.name.is_some()) {
        return None;
    }
    let rhs = args[1].value.as_ref()?;
    match args[0].value.as_ref()? {
        Expr::Sym(n, _) => Some((n.as_bytes(), rhs)),
        Expr::Const(Const::Str(Some(n)), _) => Some((n, rhs)),
        _ => None,
    }
}

/// Bind the symbol `symr` in base to a promise of `code_r` in the base
/// namespace; a binding of one of cmp.R's `safeBaseInternals` is kept as
/// base's shipped definition.
fn bind_promise(cx: &mut Cx, symr: Root<'_>, code_r: Root<'_>) -> Result<(), String> {
    cx.scope(|cx, s| {
        let p = s.out(cx);
        let pr = p.root();
        cx.build(p, |cx| {
            let ns = cx.base_namespace().sexp();
            // SAFETY: the code is rooted and the namespace immortal; a
            // PROMSXP's fields are value (R_UnboundValue: not yet forced),
            // code and environment (GNU R's mkPROMISE).
            let x = unsafe { cx.alloc_node_raw(PROMSXP, cx.unbound().sexp(), code_r.bind(cx).sexp(), ns)? };
            // SAFETY: fresh.
            Ok(unsafe { Ref::from_sexp(x, cx) })
        })
        .map_err(|e| failed(cx, e))?;
        let base = s.root(cx, cx.base_env());
        cx.define_var(symr, pr, base).map_err(|e| failed(cx, e))?;
        // SAFETY: an immortal symbol.
        if let Some(i) = unsafe { crate::cenv::safe_internal(cx, symr.bind(cx).sexp()) } {
            let g = cx.global(pr.bind(cx));
            let st = crate::prims::state(cx);
            let mut v = st.shipped.borrow_mut();
            if v.len() < crate::cenv::SAFE_BASE_INTERNALS.len() {
                v.resize_with(crate::cenv::SAFE_BASE_INTERNALS.len(), || None);
            }
            v[i] = Some(g);
        }
        Ok(())
    })
}

/// Mark the function literals of a binding's code that are not inside
/// another function as base's installed byte code (the closures they make
/// are the ones GNU R's build compiled).
///
/// # Safety
/// `e` is live and seen by no R code.
unsafe fn mark_literals(cx: &Cx, e: Sexp) {
    let nil = cx.nil().sexp();
    let function = crate::prims::state(cx).syms.function;
    // SAFETY: the caller's contract.
    unsafe {
        if e.typ() != LANGSXP {
            return;
        }
        if e.car() == function {
            crate::jit::mark_installed_literal(e);
            return;
        }
        let mut a = e;
        while a != nil && matches!(a.typ(), LANGSXP | LISTSXP) {
            mark_literals(cx, a.car());
            a = a.cdr();
        }
    }
}

/// The text of the error `e`, which is resolved.
fn failed(cx: &mut Cx, e: robigo_rtcore::RError) -> String {
    let m = crate::repl::error_text(cx, &e);
    cx.resolve_exit(e, None);
    m.trim_end().to_owned()
}

/// Bind the primitives and internals of these that robigo-rt does not
/// define to the not-implemented builtins; how many. Each stub has names.c's
/// `eval` column: a special's stub is a SPECIALSXP (its arguments not
/// evaluated), as `typeof()` and cmp.R see it.
fn stubs_for(cx: &mut Cx, primitives: &[&'static str], internals: &[&'static str]) -> usize {
    use robigo_rtbuiltins::names::{internal_eval, primitive_eval};
    let st = crate::prims::state(cx);
    let have = |name: &str, internal: bool| st.defs.iter().any(|d| d.name == name && d.internal() == internal);
    let stub = |name: &'static str, eval: i32, internal: bool| {
        let kind = match (eval % 10 == 1, internal) {
            (true, false) => Kind::Builtin(not_yet_primitive, crate::prims::Inline::None),
            (true, true) => Kind::Builtin(not_yet_internal, crate::prims::Inline::None),
            (false, false) => Kind::Fn(not_yet_primitive_special),
            (false, true) => Kind::Fn(not_yet_internal_special),
        };
        PrimDef { name, kind, eval, arity: -1 }
    };
    let mut defs = Vec::new();
    for &p in primitives {
        if !have(p, false) {
            defs.push(stub(p, primitive_eval(p.as_bytes()).map_or(1, i32::from), false));
        }
    }
    for &p in internals {
        if !have(p, true) {
            defs.push(stub(p, internal_eval(p.as_bytes()).map_or(11, i32::from), true));
        }
    }
    let n = defs.len();
    crate::define_builtins(cx, &defs);
    n
}

/// The name a stub was called by: the call's function when it is a symbol.
fn called_name(cx: &Cx, call: Root<'_>) -> String {
    match call.bind(cx).as_cons().and_then(|c| c.car().as_sym()) {
        Some(s) => String::from_utf8_lossy(s.name_bytes()).into_owned(),
        None => "?".into(),
    }
}

/// A primitive of the bound that robigo-rt does not implement yet.
fn not_yet_primitive(cx: &mut Cx, call: Root<'_>, _: Args<'_>, _: Root<'_>, _: Out<'_>) -> RResult<()> {
    let msg = format!("robigo: the primitive '{}' is not implemented yet", called_name(cx, call));
    Err(cx.error_call(Some(call), &msg))
}

/// A special primitive of the bound that robigo-rt does not implement yet.
fn not_yet_primitive_special(cx: &mut Cx, call: Root<'_>, _: Root<'_>, rho: Root<'_>, out: Out<'_>) -> RResult<()> {
    let _ = out;
    eval_stub_args(cx, call, rho)?;
    let msg = format!("robigo: the primitive '{}' is not implemented yet", called_name(cx, call));
    Err(cx.error_call(Some(call), &msg))
}

/// A special `.Internal` of the bound that robigo-rt does not implement yet.
fn not_yet_internal_special(cx: &mut Cx, call: Root<'_>, _: Root<'_>, rho: Root<'_>, out: Out<'_>) -> RResult<()> {
    let _ = out;
    eval_stub_args(cx, call, rho)?;
    let msg = format!("robigo: .Internal({}()) is not implemented yet", called_name(cx, call));
    Err(cx.error_call(Some(call), &msg))
}

/// Evaluate a special stub's argument expressions in `rho`, in order,
/// discarding the values: a missing or unbound argument reports GNU R's
/// error before the stub's not-implemented refusal. A special's stub
/// cannot know which arguments its implementation would force, so it
/// forces all but `...` (expanded by the callee, never forced here);
/// argument evaluation may run arbitrary code, as reaching any error
/// below already may. This is what the stubs did before they had
/// names.c's kind (as builtins their arguments arrived evaluated), and
/// what the recorded cases expect (`eapply` with its `env` missing
/// errors that way instead of reporting the unported internal).
///
/// The walk keeps every not-yet-evaluated expression rooted: `eval` may
/// collect (including under the moving debug collector), so no raw
/// `Sexp` is held across a call.
fn eval_stub_args(cx: &mut Cx, call: Root<'_>, rho: Root<'_>) -> RResult<()> {
    let dots = crate::prims::state(cx).syms.dots;
    cx.scope(|cx, s| {
        let nil = cx.nil();
        let mut a = s.root(cx, call.bind(cx).as_cons().map_or(nil, |c| c.cdr()));
        while let Some(cell) = a.bind(cx).as_cons() {
            let e = s.root(cx, cell.car());
            let next = s.root(cx, cell.cdr());
            if e.bind(cx).sexp() != dots {
                let o = s.out(cx);
                cx.eval(e, rho, o)?;
            }
            a = next;
        }
        Ok(())
    })
}

/// An `.Internal` of the bound that robigo-rt does not implement yet.
fn not_yet_internal(cx: &mut Cx, call: Root<'_>, _: Args<'_>, _: Root<'_>, _: Out<'_>) -> RResult<()> {
    let msg = format!("robigo: .Internal({}()) is not implemented yet", called_name(cx, call));
    Err(cx.error_call(Some(call), &msg))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// mkRbase's `sed -e "s:@WHICH@:...:"` has no `g`: the first occurrence
    /// on each line, every line.
    #[test]
    fn substitutions_replace_the_first_occurrence_on_each_line() {
        let b = b"a <- \"@W@\"; b <- \"@W@\"\nc <- \"@W@\"\nnone\n@W@";
        let r = sed_first_per_line(b, b"@W@", b"/usr/bin/which");
        assert_eq!(
            String::from_utf8(r).unwrap(),
            "a <- \"/usr/bin/which\"; b <- \"@W@\"\nc <- \"/usr/bin/which\"\nnone\n/usr/bin/which"
        );
    }

    #[test]
    fn the_bound_parses_and_names_files_in_collation_order() {
        let b = Bound::get();
        assert!(b.closures.len() >= 86, "{}", b.closures.len());
        assert!(b.closures.iter().any(|c| c.name == "cat" && c.file == "cat.R"));
        assert!(b.primitives.contains(&"UseMethod"));
        assert!(b.internals.contains(&"cat"));
        let files = b.files();
        let mut sorted = files.clone();
        sorted.sort_by_key(|f| (f.contains('/'), *f));
        assert_eq!(files, sorted);
        // `New-Internal.R` before `as.R`: bytes, not a locale's order
        let ni = files.iter().position(|f| *f == "New-Internal.R").unwrap();
        let as_ = files.iter().position(|f| *f == "as.R").unwrap();
        assert!(ni < as_);
    }

    #[test]
    fn the_pin_is_r_src_sh_s() {
        let sh = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../../scripts/r-src.sh")).unwrap();
        assert!(sh.contains(&format!("sha256={RSRC_SHA256}\n")), "scripts/r-src.sh pins another tarball");
    }
}

/// What [`stage0`] did: the top-level expressions it evaluated, and those
/// that failed (their first lines and the error), in file order.
#[derive(Debug, Default)]
pub struct Stage0 {
    pub exprs: usize,
    pub failed: Vec<(usize, String)>,
}

/// GNU R's boot of base (m2m3-plan §B L2's stage 0, L5's boot):
/// `setup_Rmainloop`'s `R_ReplFile(fp, R_BaseNamespace)` of
/// `home/library/base/R/base`, each top-level expression evaluated in the
/// base namespace at the top level, its value printed if visible. What the
/// file is decides the boot, as in GNU R: a build that has no databases yet
/// has base's whole source there (`scripts/rt-home.sh`: eager, every name
/// of base's files bound); after base's database rule it is
/// `baseloader.R`, whose `..lazyLoad` binds base from `base.rdb`
/// (`scripts/rt-home-db.sh`). Before it, as `InitNames` and `InitGraphics`
/// do: names.c's primitives and internals robigo-rt lacks bound to the
/// not-implemented builtins, and `.Device`/`.Devices`.
///
/// GNU R stops at an error (its base has none); robigo-rt records it and
/// goes on, so one run lists every expression a missing builtin stops.
// R: main.c:R_ReplFile, setup_Rmainloop
pub fn stage0(cx: &mut Cx, home: &Path) -> Result<Stage0, String> {
    let mut st = Stage0::default();
    // InitNames: every primitive and internal of names.c's table bound
    let prims: Vec<&'static str> = robigo_rtbuiltins::names::PRIMITIVES.iter().map(|p| p.0).collect();
    let internals: Vec<&'static str> = robigo_rtbuiltins::names::INTERNALS.iter().map(|p| p.0).collect();
    stubs_for(cx, &prims, &internals);
    init_graphics(cx)?;
    repl_file(cx, &home.join("library/base/R/base"), &mut st)?;
    // R_LoadProfile(R_OpenSysInitFile(), baseNSenv): the system profile,
    // in the base namespace, the same way (setup_Rmainloop's next steps,
    // the locks, .OptRequireMethods, the site and user profiles, .First.sys
    // and the JIT, are L5's boot)
    repl_file(cx, &home.join("library/base/R/Rprofile"), &mut st)?;
    lock_base(cx).map_err(|e| failed(cx, e))?;
    Ok(st)
}

/// What `setup_Rmainloop` does after the system profile and the locks,
/// as R_common_command_line's options leave it: whether to read the site
/// profile (`LoadSiteFile`) and the user's (`LoadInitFile`), to restore
/// `.RData` (`RestoreAction`), and `R_Quiet`.
#[derive(Clone, Copy, Debug)]
pub struct AfterProfile {
    pub site_file: bool,
    pub init_file: bool,
    pub restore: bool,
    pub quiet: bool,
}

/// `setup_Rmainloop` after the system profile and the locks: the call of
/// `.OptRequireMethods()`, the site profile (`R_PROFILE`, else
/// `R_HOME/etc/Rprofile.site`) in the global environment, `.Library.site`
/// removed from it, the user's profile (`R_PROFILE_USER`, else
/// `./.Rprofile`, else `$HOME/.Rprofile`), `R_InitialData` (`.RData`
/// restored), then `.First()` and `.First.sys()`. An error in a profile
/// ends that file's expression only (R_ReplFile); one in the others is
/// `check_session_exit`'s: false, R halts, unless `options(error)` or
/// `options(catch.script.errors)` say go on. The greeting (not R_Quiet) is
/// the front end's; the JIT's start (`R_init_jit_enabled`) is not run yet.
// R: main.c:setup_Rmainloop, startup.c:R_OpenSiteFile, sys-unix.c:R_OpenInitFile,
// startup.c:R_RestoreGlobalEnv, saveload.c:R_RestoreGlobalEnvFromFile
pub fn after_profile(cx: &mut Cx, home: &Path, a: AfterProfile, st: &mut Stage0) -> bool {
    use std::os::unix::ffi::OsStrExt;
    // .OptRequireMethods: found from the global environment, called in base
    if !call_startup(cx, b".OptRequireMethods", |cx| cx.global_env(), |cx| cx.base_env()) {
        return false;
    }
    let profile = |cx: &mut Cx, var: &str| -> Option<Option<std::path::PathBuf>> {
        let v = std::env::var_os(var)?;
        if v.is_empty() {
            return Some(None);
        }
        let e = crate::connections::r_expand_file_name(cx, v.as_bytes()).ok()?;
        Some(Some(std::path::PathBuf::from(std::ffi::OsStr::from_bytes(&e))))
    };
    let run = |cx: &mut Cx, f: Option<std::path::PathBuf>, st: &mut Stage0| {
        if let Some(f) = f.filter(|f| std::fs::File::open(f).is_ok()) {
            // (a file that does not parse is R_ReplFile's error at its end)
            if let Err(m) = repl_file_in(cx, &f, st, |cx| cx.global_env()) {
                st.failed.push((0, m));
            }
        }
    };
    if a.site_file {
        let f = profile(cx, "R_PROFILE").unwrap_or_else(|| Some(home.join("etc/Rprofile.site")));
        run(cx, f, st);
    }
    // the system profile's active binding for .Library.site in the global
    // environment goes (its writes in the site profile reached base's)
    let removed = cx.scope(|cx, s| {
        let sym = cx.install_rooted(s, b".Library.site")?;
        let g = s.root(cx, cx.global_env());
        cx.remove_var_from_frame(sym, g)
    });
    if let Err(e) = removed {
        cx.resolve_exit(e, None);
    }
    if a.init_file {
        let f = match profile(cx, "R_PROFILE_USER") {
            Some(f) => f,
            None => Some(std::path::PathBuf::from(".Rprofile"))
                .filter(|f| f.is_file())
                .or_else(|| std::env::var_os("HOME").map(|h| std::path::PathBuf::from(h).join(".Rprofile"))),
        };
        run(cx, f, st);
    }
    // R_InitialData: sys.load.image(".RData", R_Quiet) in the global
    // environment (base has sys.load.image, so GNU R calls it)
    if a.restore {
        let quiet = if a.quiet { "TRUE" } else { "FALSE" };
        let src = format!("sys.load.image(\".RData\", {quiet})\n");
        if !eval_startup(cx, src.as_bytes(), |cx| cx.global_env()) {
            return false;
        }
    }
    // .First: found from and called in the global environment; .First.sys:
    // found in base's namespace, called in base
    call_startup(cx, b".First", |cx| cx.global_env(), |cx| cx.global_env())
        && call_startup(cx, b".First.sys", |cx| cx.base_namespace(), |cx| cx.base_env())
}

/// `R_findVar(name, from)`, and when it is a closure `eval(lang1(name),
/// rho)` at the top level: false when an error ended it and
/// `check_session_exit` says R halts.
fn call_startup(
    cx: &mut Cx,
    name: &[u8],
    from: for<'g> fn(&'g Cx) -> Ref<'g>,
    rho: for<'g> fn(&'g Cx) -> Ref<'g>,
) -> bool {
    let found = cx.scope(|cx, s| {
        let sym = cx.install_rooted(s, name)?;
        let env = s.root(cx, from(cx));
        let o = s.out(cx);
        let v = o.root();
        cx.find_var(sym, env, o)?;
        Ok::<bool, robigo_rtcore::RError>(v.bind(cx).sexptype() == CLOSXP)
    });
    match found {
        Ok(true) => {}
        Ok(false) => return true,
        Err(e) => {
            cx.resolve_exit(e, None);
            return true;
        }
    }
    let mut src = b"`".to_vec();
    src.extend_from_slice(name);
    src.extend_from_slice(b"`()\n");
    eval_startup(cx, &src, rho)
}

/// `src`'s one call evaluated in `rho` at the top level, its value not
/// printed: false when an error ended it and `check_session_exit` says R
/// halts (the error reported where it was raised).
fn eval_startup(cx: &mut Cx, src: &[u8], rho: for<'g> fn(&'g Cx) -> Ref<'g>) -> bool {
    let text = robigo_syntax::lexable(src);
    let source = robigo_syntax::Source::new(&text, src);
    let arena = robigo_syntax::Arena::new();
    let Ok(exprs) = robigo_syntax::parse_program(&arena, source) else { return true };
    let ok = cx.scope(|cx, s| {
        let e = s.out(cx);
        let er = e.root();
        let g = s.root(cx, cx.global_env());
        let base = s.root(cx, cx.base_env());
        let env = s.root(cx, rho(cx));
        cx.repl_toplevel(g, base, |cx| {
            crate::reader::lower_one(cx, &exprs[0], e)?;
            let o = cx.scope(|cx, s| {
                let o = s.out(cx);
                crate::eval(cx, er, env, o)
            });
            o
        })
        .expect("robigo: an exit that passed the top level")
    });
    ok || crate::repl::check_session_exit(cx)
}

/// `setup_Rmainloop`'s locks right after the system profile: base's
/// namespace and its bindings (one set, shared with `baseenv()`), then
/// `baseenv()` itself, then `.Device` and `.Devices` unlocked again for
/// graphics.
// R: main.c:setup_Rmainloop
pub fn lock_base(cx: &mut Cx) -> RResult<()> {
    cx.scope(|cx, s| {
        let ns = s.root(cx, cx.base_namespace());
        cx.lock_environment(ns, true)?;
        let base = s.root(cx, cx.base_env());
        cx.lock_environment(base, false)?;
        for name in [&b".Device"[..], b".Devices"] {
            let sym = cx.install_rooted(s, name)?;
            cx.unlock_binding(sym, base)?;
        }
        Ok(())
    })
}

/// `R_ReplFile(fp, R_BaseNamespace)` of one file, into `st`: each
/// top-level expression evaluated in the base namespace at the top level,
/// its value printed if visible, the deferred warnings after it
/// ([`repl_eval_toplevel`], `Rf_ReplIteration`'s too).
// R: main.c:R_ReplFile
pub fn repl_file(cx: &mut Cx, path: &Path, st: &mut Stage0) -> Result<(), String> {
    repl_file_in(cx, path, st, |cx| cx.base_namespace())
}

/// [`repl_file`] in the environment `rho` gives (the site's and the user's
/// profiles run in the global environment).
pub fn repl_file_in(
    cx: &mut Cx,
    path: &Path,
    st: &mut Stage0,
    rho: for<'g> fn(&'g Cx) -> Ref<'g>,
) -> Result<(), String> {
    let bytes = std::fs::read(path).map_err(|e| format!("{}: {e}", path.display()))?;
    let file = path.file_name().map(|f| f.to_string_lossy().into_owned()).unwrap_or_default();
    // R_Parse1File, expression after expression: robigo-syntax parses the
    // file at once, as the repeated calls would
    let text = robigo_syntax::lexable(&bytes);
    let source = robigo_syntax::Source::new(&text, &bytes);
    let arena = robigo_syntax::Arena::new();
    let exprs = robigo_syntax::parse_program(&arena, source)
        .map_err(|e| format!("{}: {}", path.display(), robigo_syntax::format_parse_error(source, "", &e)))?;
    // R_ReplFile's savestack
    let savestack = cx.pp_top();
    for e in &exprs {
        st.exprs += 1;
        // under PROTECT(R_CurrentExpr), unprotected before the print
        let r = repl_eval_toplevel(cx, e, &[], rho, savestack, (1, 0));
        if let Err(m) = r {
            let line = robigo_syntax::line_col(&text, e.span().start as usize).0;
            let m = m.unwrap_or_else(|| "lowering failed".into());
            st.failed.push((line, format!("{file}: {}", m.trim_end())));
        }
    }
    Ok(())
}

/// The PARSE_OK body `R_ReplFile` and `Rf_ReplIteration` share, for one
/// parsed top-level expression: `R_PPStackTop = savestack`, then at the top
/// level `R_Visible = FALSE`, `eval(expr, rho)`, `.Last.value`, the value
/// printed by `PrintValueEnv(value, rho)` if visible, then the deferred
/// warnings (`PrintWarnings`). `warnings` are the parse's (the lexer's),
/// raised first. `pp` is the protections GNU R's loop holds
/// during the evaluation and during the print (robigo-rtcore's ppacct).
/// The error, if one ended it, comes back as its report's text (written
/// where it was raised); a failure to lower the expression as `None`.
// R: main.c:Rf_ReplIteration, R_ReplFile
pub(crate) fn repl_eval_toplevel(
    cx: &mut Cx,
    expr: &robigo_syntax::Expr<'_>,
    warnings: &[String],
    rho: for<'g> fn(&'g Cx) -> Ref<'g>,
    savestack: i32,
    pp: (i32, i32),
) -> Result<(), Option<String>> {
    // a C routine's imbalance does not outlive its statement
    cx.set_pp_top(savestack);
    cx.scope(|cx, s| {
        let e = s.out(cx);
        let er = e.root();
        let g = s.root(cx, cx.global_env());
        let base = s.root(cx, cx.base_env());
        let env = s.root(cx, rho(cx));
        let o = s.out(cx);
        let or = o.root();
        let mut msg = None;
        let mut lowered = true;
        // R_Toplevel, the session's record: the handler and restart stacks
        // kept (the global calling handlers last from one expression to the
        // next), and an error's jump lands on it
        let done = cx
            .repl_toplevel(g, base, |cx| {
                // the parse's objects are made at the top level
                // (R_Parse1Buffer, R_Parse1File), so an error there lands on it;
                // so are the lexer's warnings (`warning()`, no call), which
                // print with the statement's own
                if let Err(err) = warnings.iter().try_for_each(|w| cx.warning(w)) {
                    msg = Some(crate::repl::error_text(cx, &err));
                    return Err(err);
                }
                if let Err(err) = crate::reader::lower_one(cx, expr, e) {
                    lowered = false;
                    return Err(err);
                }
                cx.set_visible(false);
                let r = cx.with_pp_excess(pp.0, |cx| crate::eval(cx, er, env, o)).and_then(|()| {
                    cx.set_last_value(or)?;
                    if cx.visible() {
                        cx.with_pp_excess(pp.1, |cx| crate::print::print_value_env(cx, or, env))?;
                    }
                    Ok(())
                });
                if let Err(e) = &r {
                    msg = Some(crate::repl::error_text(cx, e));
                }
                r
            })
            .expect("robigo: an exit that passed the top level");
        if !done {
            // a jump to the top level: the error (or restart) reported
            // where it was raised
            return Err(if lowered { Some(msg.unwrap_or_default()) } else { None });
        }
        crate::repl::print_warnings(cx);
        Ok(())
    })
}
